package com.aoo.bcg.poker;import java.util.*;import java.util.stream.*;/**海南地主牌九类组合。*/final class HndzpRules{enum Type{PASS,SINGLE,PAIR,TRIPLE,FOUR,STRAIGHT,FLUSH,FULL_HOUSE,FOUR_PLUS_ONE,STRAIGHT_FLUSH}record Play(Type type,List<Integer>cards,int value,int chainLength){Play{cards=List.copyOf(cards);}}static List<Integer>deck(boolean jokers){return PokerCardCodec.deck(jokers?54:52);}static int rank(int c){return PokerCardCodec.rank(c);}static int point510k(int c){return 0;}static Play classify(Type d,Collection<Integer>in){List<Integer>c=List.copyOf(in);Map<Integer,Long>m=c.stream().collect(Collectors.groupingBy(HndzpRules::rank,TreeMap::new,Collectors.counting()));int min=m.keySet().stream().mapToInt(x->x).min().orElseThrow(),max=m.keySet().stream().mapToInt(x->x).max().orElseThrow();boolean flush=c.stream().map(PokerCardCodec::suit).distinct().count()==1,straight=c.size()==5&&m.size()==5&&max-min==4;boolean ok=switch(d){case SINGLE->c.size()==1;case PAIR->c.size()==2&&m.size()==1;case TRIPLE->c.size()==3&&m.size()==1;case FOUR->c.size()==4&&m.size()==1;case STRAIGHT->straight&&!flush;case FLUSH->c.size()==5&&flush&&!straight;case FULL_HOUSE->c.size()==5&&m.values().containsAll(List.of(2L,3L));case FOUR_PLUS_ONE->c.size()==5&&m.containsValue(4L);case STRAIGHT_FLUSH->straight&&flush;case PASS->false;};if(!ok)throw new IllegalArgumentException("invalid HNDZP "+d);return new Play(d,c,max,m.size());}static boolean beats(Play n,Play p){return p==null||n.type()==p.type()&&n.cards().size()==p.cards().size()&&n.value()>p.value()||power(n.type())>power(p.type());}private static int power(Type t){return t.ordinal();}static int prize(Play p,boolean four20,boolean doubleJoker,boolean ignored){if(four20&&(p.type()==Type.FOUR||p.type()==Type.FOUR_PLUS_ONE))return 20;if(doubleJoker&&p.cards().stream().filter(c->PokerCardCodec.rank(c)>=16).count()==2)return 10;return 0;}}
